import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.hwbV7reR.js";const u=JSON.parse('{"title":"Ошибки и повтор запросов","description":"","frontmatter":{},"headers":[],"relativePath":"errors.md","filePath":"errors.md","lastUpdated":1791695486000}'),a={name:"errors.md"};function c(n,t,i,s,_,l){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ошибки-и-повтор-запросов" tabindex="-1">Ошибки и повтор запросов <a class="header-anchor" href="#ошибки-и-повтор-запросов" aria-label="Permalink to &quot;Ошибки и повтор запросов&quot;">​</a></h1><p>Прикладные ошибки возвращают <code>{&quot;detail&quot;:&quot;machine_readable_code&quot;}</code>. Полный <a href="https://github.com/UndercoreCo/orchestrator/blob/main/contracts/errors.json" target="_blank" rel="noreferrer">каталог</a> содержит возможные HTTP-статусы; наличие кода в каталоге не означает, что его возвращает каждый маршрут.</p><table tabindex="0"><thead><tr><th>Ситуация</th><th>Действие backend</th></tr></thead><tbody><tr><td>401 <code>unauthorized</code></td><td>Исправить служебную авторизацию; не просить пароль пользователя VPN</td></tr><tr><td>404 <code>not_found</code></td><td>Проверить пару connection_id/device_id; не раскрывать чужое назначение</td></tr><tr><td>422 <code>invalid_request</code></td><td>Исправить запрос; неизменный запрос не повторять автоматически</td></tr><tr><td>422 <code>unsupported_format</code>, <code>qr_unavailable</code></td><td>Использовать возможности адаптера; не обрезать конфиг для QR</td></tr><tr><td>409 <code>client_upgrade_required</code></td><td>Проверить возможности клиента; не выдавать ему неизвестный формат</td></tr><tr><td>410 <code>access_unavailable</code>, <code>grant_expired</code></td><td>Проверить срок и отзыв; повтор не заменяет выдачу права backend</td></tr><tr><td>429 <code>recovery_cooldown</code></td><td>Выдержать паузу политики; не менять device_id или ключ ради обхода</td></tr><tr><td>503 <code>connection_busy</code></td><td>Занята блокировка или очередь исходящих запросов; повторить позже с прежней идентичностью</td></tr><tr><td>503 <code>lease_waiting</code></td><td>Продолжить ту же операцию/ревизию после ожидания; не создавать новое назначение</td></tr><tr><td>503 недоступного узла/процесса</td><td>Ограниченные повторы с задержкой и общим дедлайном; сообщить оператору при исчерпании</td></tr><tr><td>Несовпадение server identity, владельца или ревизии</td><td>Сверить состояние; не обходить проверки и не считать это пустым результатом</td></tr><tr><td>Таймаут без ответа</td><td>Результат неизвестен. Повторить исходную операцию со стабильной идентичностью</td></tr></tbody></table><p>Не все 409/503 допускают одинаковые повторы. Сверяйте машинный код и контекст операции. Для первоначального create стабильность задаёт device_id, для renew и switch — ключ операции, для recover — expected_revision. Политика backend должна иметь предел попыток и времени. Интервал systemd worker не является рекомендацией частоты клиентских запросов.</p><p>Неизвестный код ошибки сохраняйте как безопасные метаданные вместе с HTTP-статусом и названием операции. Не записывайте токены, конфигурации и необработанные тела ответов. Ошибка reverse proxy может иметь другое тело: сначала проверяйте статус и Content-Type, затем разбирайте JSON. Ошибки маршрутизации/параметров FastAPI также могут отличаться от прикладного envelope.</p>',5)])])}const h=e(a,[["render",c]]);export{u as __pageData,h as default};
